from collections import defaultdict
from typing import List

def change_array(a: List[int], q: List[List[str, int]]) -> List[int]:
    modifications = {}
    for op in q:
        op_char, x = op[0], op[1]
        if op_char == '>':
            modifications[x] = -a[x]
        elif op_char == '<':
            modifications[x] = a[x]

    ranks = []
    prev_val = float('-inf')
    for i in range(len(a)):
        if i in modifications:
            if modifications[i] == -prev_val:
                ranks.append(0)
            else:
                ranks.append(1)
            prev_val = modifications[i]
        else:
            ranks.append(0)

    result = [a[i] for i in range(len(a))]
    for i in range(len(a)):
        rank = ranks[i]
        if prev_val != float('-inf') and prev_val >= result[i]:
            continue
        if prev_val != float('-inf') and prev_val < a[i]:
            rank = 1
        if result[i] > a[i]:
            result[i] = a[i]
        direction = '-' if rank == 0 else '+'
        if prev_val != float('-inf') and prev_val > a[i]:
            direction = '-' if direction == '-' else '+'
        if direction == '-':
            result[i] = prev_val
        else:
            result[i] = a[i]
        prev_val = result[i]

    return result

# Example usage
