    for i in range(1, n):
        a_max_gain[i] = max(a_max_gain[i], a_max_gain[i - 1])

    memo = {}
    def query_left(l, r, k):
        nonlocal a_max_gain

        query_gain = 0
        left_overlap = 0
        can_true = l < r

        # Account for subsegments not within the query's range
        if can_true and bisect_right(a_max_gain, a_max_gain[r - 1]) <= k:
            query_gain += k
            left_overlap = k
            can_true = False

        # Add the start of the current segment to aggregate into a_p[0]
        curr_max = max(a_max_gain[l], query_gain + a_max_gain[l - 1] + left_overlap, a_max_gain[l - left_overlap] + left_overlap)
        a_max_gain[l] = curr_max

        curr_gain = curr_max - (r - l + 1) if can_true and l <= r else curr_max
        query_gain += curr_gain

        while len(queries) and queries[0][0] <= l:
            query_index, left, right, k = queries.pop(0)
            if memo[query_index] != k:
                memo[query_index] = k
            max_gain = a_max_gain[right - 1] - (max(a_max_gain[left - 1], 0) if left > 0 else 0) if memo[query_index] >= k else 0
            results.append(max_gain)
        return query_gain

    # Initialize memoization for cheaper second instance query
    memo[0] = 0
    stack = [0]
    for query in q:
        i, l, r, k = query
        if i in memo:
            k -= memo[i]
        if not memo:
            queries.append((i, l, r, k))
        else:
            while len(stack) >= 2 and stack[-2] >= l:
                prev, _, _, prev_k = stack.pop()
                if not mem[prev] or k <= mem[prev] - prev_k:
                    queries.append((prev, l, r + prev, k - mem[prev] + prev_k if mem[prev] else 0))
                if prev <= r:
                    stack.append((prev + 1, max(a_max_gain[prev + 1] - (a_max_gain[l] if l != 0 else 0), max_gain_p[k][prev + 1])))
                if k < prev_k:
                    k -= prev_k
                if k == 0:
