from math import factorial

def ways_to_distribute_medals():
    n, _ = [int(x) for x in input().split()]
    m = int(input())

    routes = [[] for _ in range(n)]
    for _ in range(m):
        u, v, c = [int(x) for x in input().split()]
        routes[u-1].append((v-1, c))
        routes[v-1].append((u-1, c))

    g1, g2, s1, s2 = [int(x) for x in input().split()]

    def is_valid(num, has_juniors):
        def dfs(city, visited, dist):
            if city in visited and dist >= num or dist < 1:
                return 1
            if dist == num:
                return 2  # juniors
            count = 0
            for next_city, _ in routes[city]:
                if next_city not in visited and dfs(next_city, visited | {next_city}, dist + _):
                    count += dfs(next_city, visited | {next_city}, dist + _)
            return count

        visited = {city: dist if dist >= num else 0 }
        return is_used(num, has_juniors) and is_used(num * 2 + has_juniors, not has_juniors) and dfs(num, visited, 1)

    def is_used(num, has_juniors):
        return factoriel(num - min(num * 2 + has_juniors, n - 1)) / (factoriel(num - has_juniors) * factorial(n - num)) >= 2

    total_ways = 0
    from itertools import combinations

    for g in range(1, g2 + 1):
        for s in range(1, s2 + 1):
            if g1 <= g <= g2 and s1 <= s <= s2:
                total_ways += sum(is_valid(num + 1, has_juniors) for num, has_juniors in combinations(range(1, n), n // 2))

    return total_ways

def factoriel(num):
    if num <= 1:
        return 1
    return num * factoriel(num - 1)

print(ways_to_distribute_medals())
