        return
    i, j = start, end
    while i >= 0 and j < len(s):
        if s[i] != s[j]:
            break
        i -= 1
        j += 1
    if i + 1 < i + j:
        return i + 1
    return 2

class StringSplitter:
    def countStrings(self, A, B, m, n):
        ans = 0
        for k in range(len(A) + 1 - m):
            for h in range(len(B) + 1 - n):
                countWa = k
                countWb = h
                for i in range(k):
                    extend = extend_palindrome(k - i, k + i, A)
                    if extend:
                        countWa -= extend
                        countWb += extend
                for j in range(h):
                    extend = extend_palindrome(h - j, h + j, B)
                    if extend:
                        countWa += extend
                        countWb -= extend
                ans += countWa * countWb
            for i in range(k):
                extend = extend_palindrome(k - i, k + 1 + i, A)
                if extend:
                    countWa += extend
            for j in range(h):
                extend = extend_palindrome(h - j, h + 1 + j, B)
                if extend:
                    countWb -= extend
            ans -= countWa * countWb
        return ans


