from collections import deque

def findIntersectionPoint(x1, y1, x2, y2, edges):
    """
    Finds the next intersection point on an unidirectional path starting from a stone
    If two stones collide, we count them as a unique stone
    """
    stack = deque([(x1, y1, (0, 0))])  # (x, y, (colliding actor, first seen index))

    intersections = set()
    seen = {}

    while stack:
        (x0, y0, collision) = stack.popleft()

        if (x0, y0) in seen:
            return seen[(x0, y0)]  # Return collision index when another stone is seen
        seen[(x0, y0)] = len(intersections)  # Save collision point id

        if x0 != collision[0] and y0 != collision[1]:
            intersections.add((x0, y0))
            continue

        if not collision or collision == (x0, y0):
            continue  # Skip stones which are themselves

        if collision[2] == x0 and collision[1] == y0:
            return seen[(x0, y0)]  # return an if there's a same point that hasn't seen

        dx = x0 - collision[0]
        dy = y0 - collision[1]

        for i in range(-1, 2):
            for k in range(-1, 2):
                newx = x0 + (i if i > 0 else -i) * dx//abs(dx)
                newy = y0 + (k if k > 0 else -k) * dy//abs(dy)
                stack.append((newx, newy, (collision[0], collision[1])))

    return -1  # if we crawl the entire graph, return -1 as there's no collisions


