        if u < v:
            u, v = (u, v) if u != v + n else (v, u)
        cost = min(c, n * c)
        time_penalty += c
        time_penalty += 2 * min(c * math.sqrt((u-n)**2 + (v-n)**2), c * math.sqrt((u-n)**2 + (v-(n+1))**2))
        max_cost = max(max_cost, cost + time_penalty)

