import sys

def min_char_changes(handle, k, segment_length):
    """
    Calculate the minimum number of lowercase letters to convert to uppercase to
    minimize the total number of letters after at most k transformations.
    """
    min_changes = segment_length
    for c in handle:
        if c.islower():
            min_changes += 1  # Increase by 1 for each lowercase character
    if min_changes > k:
        return 'unfeasible'
    elif (min_changes == k or handle.lower() == handle) and k % min_changes == 0:
        return str(k - min_changes)
    else:
        return str(k - min_changes + 1)

