            return root
        char = li[0]
        if not s:
            if len(li) > len(li[0]):
                li[0] += char
        branch = insert(s[1:], li[1:])
        if char not in root:
            root[char] = branch
        else:
            if s and f(root[char]):
                root[char] = branch
        return root

    for word in map(f, words):
