from math import inf

def min_changes(codeforces):
    n = len(codeforces)
    dp = [inf] * (n + 1)

    @lru_cache(None)
    def change_to_i(index, exclude):
        if index == n:
            return 0
        if exclude:
            return -inf
        dp[index] = min(dp[index], exclude + 1)
        for x in [codeforces[index], codeforces[index].lower(), codeforces[index].upper()]:
            dp[index] = min(dp[index], dp[index+1] + (''.join(x*2).count('a') - x.count('a')))
        dp[index] = min(dp[index], change_to_i(index + 1, True))
        return dp[index]

    return min_changes('I ' + codeforces + 'I')

