def minimize_losers(winner: int, loser: int, k: int) -> int:
    assert 1 <= winner <= 2**k
    assert 1 <= loser <= 2**k

    losers = set()
    loser_games = set()
    eliminated = {loser}
    game = {loser}

    loser_games.add(winner)
    eliminated.add(winner)

    while len(game) != 1:
        losers.update(game)
        elimination = defaultdict(int)
        while len(game) != 0:
            winner = game.pop()
            if winner != loser:
                if eliminated_wins := eliminated.intersection(winner/games):
                    elimination[eliminated_wins[0]] += 1
                loser_games.add(winner)
                eliminated.add(winner)
                eliminated_wins = eliminated.wins()
                eliminated.add(loser)

        eliminated = elimination.pop()
        game = {**eliminated}

    return len(loser_games)

def maximize_games(n: int, k: int, fans: set[int]) -> int:
    if n == 1:
        return len(fans)

    number = 2**(n-1)
    return minimize_losers(1, fans.pop(), number) + minimize_losers(2**n + number, fans.pop(), number)

