from collections import defaultdict

def build_tree(edges, vals):
    n = len(edges) + 1
    parents = {i: i for i in range(n)}

    for u, v, c in edges:
        parents[v] = u

    non_letter_indices = []
    for i in range(len(vals)):
        if vals[i] == '.':
            non_letter_indices.append(i)

    node_to_non_lett = {}
    distance = 1
    for p, q in parents.items():
        if q < n // 2:
            continue
        v = q
        while v != p:
            node_to_non_lett[v] = distance
            v = parents[v]
        distance += 1

    state = {i: None for i in range(n)}
    state[0] = 'top'
    while state:
        node = state.pop()
        if node in non_letter_indices:
            continue
        child_state = {}
        distance = node_to_non_lett.get(node)
        if distance:
            child_state[node] = 'children'
            for v in parents[node]:
                if v not in child_state:
                    child_state[v] = 'children'
                if node_to_non_lett[v] == child_state[v] - 1:
                    child_state[v] = 'top'
        else:
            child_state[parents[node]] = 'next-depth'
            parents[node] = None

        prev_state = {}
        for v, istate in state.items():
            if 0 <= distance - 2 < len(node_to_non_lett) and node_to_non_lett[distance-2] == istate:
                if istate == 'routes' or istate == 'top':
                    continue
                lay_oveer = node_to_non_lett[v] + 1 < distance - 1 and node_to_non_lett[v] + 1 == istate
                if lay_oveer:
                    lay_oveer &= node_to_non_lett[v] == child_state[v]
                    if lay_oveer:
                        child_state[v] = 'next-depth'
                if lay_oveer:
                    prev_state[v] = 'next-depth'
                    distance = distance - 1
        if 0 <= distance - 2 < len(node_to_non_lett) and node_to_non_lett[distance - 2] == 'next-depth':
            child_state[tuple((parents[j] for j in range(distance - 2, distance)))] = 'top'

        if 'next-depth' in child_state:
            for each in child_state['next-depth']:
                state[each] = 'next-depth'
        elif 'top' in child_state:
            state[each] = 'top'

        state.update(child_state)
        state.update(prev_state)

    return state

