from collections import defaultdict

# Create a string and add it's reverse to a hashmap
def add_reverse_string_to_map(str_value, hashmap):
    reverse_str_value = str_value[::-1]
    if reverse_str_value in hashmap:
        hashmap[reverse_str_value] += 1
    else:
        hashmap[reverse_str_value] = 1
    return str_value

# Replace invalid palindrome strings with the string itself and put into hashmap to solve "generate palindrome" problem
def generate_palindrome_hashmap(str_value, hashmap):
    while str_value != reverse_str_value:
        add_reverse_string_to_map(str_value, hashmap)
        if not str_value in hashmap or hashmap[str_value] == 0:
            break
        else:
            str_value = str_value[:-1]

    hashmap[str_value] -= 1
    return hashmap

# When the obtained palindrome string's length is less than the max_length, repeat the function, otherwise, simply got the length
def get_length(str_value, max_length):
    count_map = {}
    if len(str_value) >= max_length:
        return len(str_value)

    for i in range(len(str_value)):
        add_reverse_string_to_map(str_value[i:], count_map)

    palindrome_length = 0
    for length in count_map:
        if len(str_value) - i >= int(length):
            palindrome_length += count_map[str_value[:-1]] if str_value[:-1] in count_map else 1
    return palindrome_length

