def can_flip_to_zeros(n, a):
    zero_count = 0
    for i in range(n):
        if a[i] == 0:
            zero_count += 1

    if zero_count <= 1:
        return "NO"

    if zero_count == n:
        return "YES\n0"

    if zero_count % 3 > 0:
        zero_count -= zero_count % 3
    else:
        zero_count -= zero_count % 3

    if zero_count <= 1:
        return "NO"

    if zero_count % 32 > 0:
        return "NO"

    operations = 0
    while zero_count > 2:
        zero_count = zero_count - 2
        operations += 1

    if zero_count == 2:
        return "YES\n" + str(zero_count // 32) + " " + str(zero_count // 8) + " " + str(zero_count % 8) + " " + str(zero_count % 4)

    if zero_count % 2 < zero_count:
        half = zero_count // 2
        temp = zero_count - half
        reverse_half = (half - 1) // 2
        operations += 2
        if half:
            swap_a = half % 2
            for x in range(zero_count + 1):
                if x in range(2, zero_count + 1) and swap_a:
                    a[x - 2], a[x - 1] = a[x - 1], a[x - 2]
                else:
                    a[x - 1] = 1 - a[x - 1]
            return "YES\n" + str(operations) + " " + str(2)

        reverse_a = zero_count - half
        for x in range(zero_count + 1):
            if x in range(zero_count, 0, -2) and reverse_a:
                a[x - 1], a[x - 3] = a[x - 3], a[x - 1]
            else:
                a[x - 1] = 1 - a[x - 1]
        return "YES\n" + str(operations + 1) + " " + str(1)

