def can_make_zero(arr):
    if not arr or arr[0] == 1:
        return "NO"

    operations = 0
    visited = [False] * len(arr)

    for i in range(len(arr)):
        if arr[i] == 1:
            for j in range(i + 1, len(arr)):
                if arr[j] == 0 and not visited[j]:
                    for k in range(j + 1, len(arr)):
                        if arr[k] == 1:
                            visited[j], visited[k] = True, True
                            arr[i], arr[j], arr[k] = 0, 1, 0
                            operations += 1
                            if operations > (len(arr) // 3 + 12):
