def is_palindrome(s):
    return s == s[::-1]

def count_palindromes(a, b):
    a_palindromes = [a[0:i+1] for i in range(len(a)+1)]
    b_palindromes = [b[0:i+1] for i in range(len(b)+1)]

    for i in range(1, len(b)+1):
        left = b[i-1]
        for j in range(i):
            new_palindrome = left + b[j:(i+1)]
            if is_palindrome(new_palindrome):
                b_palindromes[i-1].append(new_palindrome)

    total_count = 0

    for a_palindrome in a_palindromes:
        for b_palindrome in b_palindromes:
            if b_palindrome and not a_palindrome.endswith(b_palindrome[0]):
                continue
            new_palindrome = ""
            for i in range(len(b_palindrome)):
                new_palindrome += b_palindrome[i]
                if is_palindrome(new_palindrome):
                    if a_palindrome.endswith(b_palindrome[i+1]):
                        total_count += len(a_palindrome)
                    else:
                        total_count += len(a_palindrome) + 1
    return total_count

