def is_palindrome(s):
    return s == s[::-1]

def count_palindromes(A, B):
    A = A.lower()
    B = B.lower()

    A_palindromes = [a for a in A if is_palindrome(a)]
    B_palindromes = [b for b in B if is_palindrome(b)]

    result = 0

    for a in A_palindromes:
        for b in B_palindromes:
            result += len(a) * len(b)

    for i in range(len(A)):
        if is_palindrome(A[i:]):
            result += len(A) - i * 2 + 1

    for i in range(len(B)):
        if is_palindrome(B[i:]):
            result += len(B) - i * 2 + 1

    return result

A = input().strip()
B = input().strip()

print(count_palindromes(A, B))
